"""In-memory inventory of SKUs and their quantities."""


class InsufficientStock(ValueError):
    """Raised when removing more units than are in stock."""


def _normalize(sku: str) -> str:
    """SKUs are case-insensitive and ignore surrounding whitespace."""
    return sku.strip().upper()


class Inventory:
    def __init__(self) -> None:
        self._stock: dict[str, int] = {}

    def add(self, sku: str, qty: int) -> None:
        key = _normalize(sku)
        self._stock[key] = self._stock.get(key, 0) + qty

    def remove(self, sku: str, qty: int) -> None:
        key = _normalize(sku)
        available = self._stock.get(key, 0)
        if qty > available:
            raise InsufficientStock(
                f"cannot remove {qty} of {key!r}: only {available} in stock"
            )
        self._stock[key] = available - qty

    def quantity(self, sku: str) -> int:
        return self._stock.get(_normalize(sku), 0)

    def report(self) -> list[tuple[str, int]]:
        items = [(sku, qty) for sku, qty in self._stock.items() if qty > 0]
        return sorted(items, key=lambda item: (-item[1], item[0]))
